class Solution {
  public int minEatingSpeed(int[] piles, int h) {
    int left = 1;
    int right = 0;
    for (int pile : piles) right = Math.max(right, pile);

    while (left < right) {
      int mid = left + (right - left) / 2;

      if (canFinish(piles, h, mid)) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }

    return left;
  }

  private boolean canFinish(int[] piles, int h, int speed) {
    long hours = 0;
    for (int pile : piles) {
      hours += (pile + speed - 1L) / speed;
      if (hours > h) return false;
    }
    return true;
  }
}

class Solution {
  public int shipWithinDays(int[] weights, int days) {
    int left = 0;
    int right = 0;

    for (int weight : weights) {
      left = Math.max(left, weight);
      right += weight;
    }

    while (left < right) {
      int mid = left + (right - left) / 2;

      if (canShip(weights, days, mid)) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }

    return left;
  }

  private boolean canShip(int[] weights, int days, int capacity) {
    int usedDays = 1;
    int load = 0;

    for (int weight : weights) {
      if (load + weight > capacity) {
        usedDays++;
        load = 0;
      }
      load += weight;
      if (usedDays > days) return false;
    }

    return true;
  }
}

class Solution {
  public int splitArray(int[] nums, int k) {
    int left = 0;
    int right = 0;

    for (int num : nums) {
      left = Math.max(left, num);
      right += num;
    }

    while (left < right) {
      int mid = left + (right - left) / 2;

      if (canSplit(nums, k, mid)) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }

    return left;
  }

  private boolean canSplit(int[] nums, int k, int limit) {
    int parts = 1;
    int currentSum = 0;

    for (int num : nums) {
      if (currentSum + num > limit) {
        parts++;
        currentSum = 0;
      }
      currentSum += num;
      if (parts > k) return false;
    }

    return true;
  }
}

class Solution {
  public int minimizedMaximum(int n, int[] quantities) {
    int left = 1;
    int right = 0;
    for (int quantity : quantities) right = Math.max(right, quantity);

    while (left < right) {
      int mid = left + (right - left) / 2;

      if (canDistribute(n, quantities, mid)) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }

    return left;
  }

  private boolean canDistribute(int n, int[] quantities, int limit) {
    long stores = 0;
    for (int quantity : quantities) {
      stores += (quantity + limit - 1L) / limit;
      if (stores > n) return false;
    }
    return true;
  }
}

import java.util.Arrays;

class Solution {
  public int maxDistance(int[] position, int m) {
    Arrays.sort(position);
    int left = 1;
    int right = position[position.length - 1] - position[0];
    int answer = 1;

    while (left <= right) {
      int mid = left + (right - left) / 2;

      if (canPlace(position, m, mid)) {
        answer = mid;
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }

    return answer;
  }

  private boolean canPlace(int[] position, int m, int distance) {
    int count = 1;
    int last = position[0];

    for (int i = 1; i < position.length; i++) {
      if (position[i] - last >= distance) {
        count++;
        last = position[i];
        if (count == m) return true;
      }
    }

    return false;
  }
}

import java.util.Arrays;

class Solution {
  public static int aggressiveCows(int[] stalls, int k) {
    Arrays.sort(stalls);
    int left = 1;
    int right = stalls[stalls.length - 1] - stalls[0];
    int answer = 0;

    while (left <= right) {
      int mid = left + (right - left) / 2;

      if (canPlace(stalls, k, mid)) {
        answer = mid;
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }

    return answer;
  }

  private static boolean canPlace(int[] stalls, int k, int distance) {
    int cows = 1;
    int last = stalls[0];

    for (int i = 1; i < stalls.length; i++) {
      if (stalls[i] - last >= distance) {
        cows++;
        last = stalls[i];
        if (cows == k) return true;
      }
    }

    return false;
  }
}

class Solution {
  public double findMedianSortedArrays(int[] nums1, int[] nums2) {
    if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);

    int m = nums1.length;
    int n = nums2.length;
    int leftSize = (m + n + 1) / 2;
    int left = 0;
    int right = m;

    while (left <= right) {
      int cut1 = left + (right - left) / 2;
      int cut2 = leftSize - cut1;

      int left1 = cut1 == 0 ? Integer.MIN_VALUE : nums1[cut1 - 1];
      int right1 = cut1 == m ? Integer.MAX_VALUE : nums1[cut1];
      int left2 = cut2 == 0 ? Integer.MIN_VALUE : nums2[cut2 - 1];
      int right2 = cut2 == n ? Integer.MAX_VALUE : nums2[cut2];

      if (left1 <= right2 && left2 <= right1) {
        if ((m + n) % 2 == 1) return Math.max(left1, left2);
        return (Math.max(left1, left2) + Math.min(right1, right2)) / 2.0;
      }

      if (left1 > right2) right = cut1 - 1;
      else left = cut1 + 1;
    }

    return 0.0;
  }
}

class Solution {
  public int findKthPositive(int[] arr, int k) {
    int left = 0;
    int right = arr.length;

    while (left < right) {
      int mid = left + (right - left) / 2;
      int missingBeforeMid = arr[mid] - mid - 1;

      if (missingBeforeMid < k) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    return left + k;
  }
}
